import type { McpToolHookInputs } from "./hook-inputs.js";

/** Inputs of the tools `hooks.template.json` calls, generated by `claude-code-hook-types`. */
export type HookInputs = McpToolHookInputs["plugin:dprint:dprint-hooks"];
/** Every field optional, nested ones too: a client may call a tool directly with fewer fields than the hook sends. */
type Loose<T> = { [K in keyof T]?: T[K] extends object ? Loose<T[K]> : T[K] };
/** A tool's input as its handler receives it. */
export type HookInput<K extends keyof HookInputs> = Loose<HookInputs[K]>;
